import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BU4O3IzQ.js";const m=JSON.parse('{"title":"AI 动态 · 2026-07-26","description":"","frontmatter":{"title":"AI 动态 · 2026-07-26","date":"2026-07-26T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-07/ai-news-2026-07-26.md","filePath":"news/2026-07/ai-news-2026-07-26.md","lastUpdated":1786092171000}'),s={name:"news/2026-07/ai-news-2026-07-26.md"};function o(i,e,c,p,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-07-26" tabindex="-1">AI 动态 · 2026-07-26 <a class="header-anchor" href="#ai-动态-·-2026-07-26" aria-label="Permalink to &quot;AI 动态 · 2026-07-26&quot;">​</a></h1><blockquote><p>截至 2026-07-26。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="「眸深智能」完成近亿元-pre-a-轮追加融资-估值半年涨-10-倍" tabindex="-1">「眸深智能」完成近亿元 Pre-A 轮追加融资，估值半年涨 10 倍 <a class="header-anchor" href="#「眸深智能」完成近亿元-pre-a-轮追加融资-估值半年涨-10-倍" aria-label="Permalink to &quot;「眸深智能」完成近亿元 Pre-A 轮追加融资，估值半年涨 10 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">36氪</span><time datetime="2026-07-26">2026-07-26</time></p><p><img src="https://img.36krcdn.com/hsossms/20260725/v2_44f27216a65b4e0e963e25dd7e66d7db@000000_oswg50341oswg893oswg380_img_000?x-oss-process=image/resize,m_mfit,w_600,h_400,limit_0/crop,w_600,h_400,g_center" alt="配图"></p><p>具身大脑公司「眸深智能」（Motion Brain）完成近亿元 Pre-A 轮追加融资，由瑾悦投资、创合汇资本及老股东徐汇资本参投。此前 5 月刚完成 3 亿元 Pre-A 轮，Pre-A+ 轮近 5 亿融资也在交割中。公司由复旦教授陈涛、前英特尔首席科学家张益民等创立，走“世界动作模型”路线，将动作映射为隐空间 Token，上半年营收已达数千万元。对读者：具身智能赛道融资热度不减，关注“动作模型”路线与 VLA 路线的分化，可跟踪其开源数据与模型进展。</p><p class="news-entry-source"><a href="https://36kr.com/p/3911162147640456?f=rss" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="monday-com-以-ai-为由裁员-20-techcrunch-统计已有-20-余家科技公司效仿" tabindex="-1">Monday.com 以 AI 为由裁员 20%，TechCrunch 统计已有 20 余家科技公司效仿 <a class="header-anchor" href="#monday-com-以-ai-为由裁员-20-techcrunch-统计已有-20-余家科技公司效仿" aria-label="Permalink to &quot;Monday.com 以 AI 为由裁员 20%，TechCrunch 统计已有 20 余家科技公司效仿&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-07-25">2026-07-25</time></p><p><img src="https://techcrunch.com/wp-content/uploads/2026/07/robot-at-desk.png?resize=1200,800" alt="配图"></p><p>项目管理软件公司 Monday.com 在 SEC 文件中宣布裁员约 20%，并将 AI 列为关键因素。TechCrunch 梳理了今年以 AI 为由进行裁员的 20 余家科技公司，包括多家知名企业。这一趋势反映出企业正通过 AI 自动化替代部分人力岗位，尤其在客服、内容生成与项目管理领域。对读者：AI 对就业结构的影响正在加速，开发者应主动向 AI 工具链开发、Agent 工程等高价值方向转型。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/07/25/the-running-list-major-tech-layoffs-in-2026-where-employers-cited-ai/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="reid-hoffman-与-mark-pincus-联合创立-ai-实验室-prentis-拟融资-1-亿美元" tabindex="-1">Reid Hoffman 与 Mark Pincus 联合创立 AI 实验室 Prentis，拟融资 1 亿美元 <a class="header-anchor" href="#reid-hoffman-与-mark-pincus-联合创立-ai-实验室-prentis-拟融资-1-亿美元" aria-label="Permalink to &quot;Reid Hoffman 与 Mark Pincus 联合创立 AI 实验室 Prentis，拟融资 1 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-07-25">2026-07-25</time></p><p><img src="https://techcrunch.com/wp-content/uploads/2024/11/GettyImages-1258942056.jpg?resize=1200,799" alt="配图"></p><p>新 AI 研究实验室 Prentis 由连续创业者 Ritankar Das 与科技巨头 Reid Hoffman、Mark Pincus 联合创立，正洽谈以 10 亿美元估值融资 1 亿美元。该实验室专注于“计算机使用模型”，押注自动化日常计算机任务将超越编程成为 AI 最大应用场景。对读者：计算机使用（Computer Use）正成为 AI 新热点，关注该领域开源项目与工具链，可能重塑 RPA 与办公自动化市场。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/07/24/prentis-new-ai-lab-co-founded-by-reid-hoffman-mark-pincus-in-talks-to-raise-100m/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="cognition-收购-ai-助手-poke-ai-人格正成为竞争壁垒" tabindex="-1">Cognition 收购 AI 助手 Poke：AI 人格正成为竞争壁垒 <a class="header-anchor" href="#cognition-收购-ai-助手-poke-ai-人格正成为竞争壁垒" aria-label="Permalink to &quot;Cognition 收购 AI 助手 Poke：AI 人格正成为竞争壁垒&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-07-25">2026-07-25</time></p><p><img src="https://techcrunch.com/wp-content/uploads/2026/04/Poke-at-3.56.23-PM.jpg?resize=1200,610" alt="配图"></p><p>AI 编码初创公司 Cognition 收购了以“像朋友一样发短信”为特色的 AI 助手 Poke，交易估值在“低九位数”范围。此举旨在将 Poke 的对话风格与交互模型融入其编码代理 Devin，反映出行业共识：AI 助手的交互方式与人格化体验正与底层模型能力同等重要。对读者：AI 产品的“人格”设计正从加分项变为核心竞争力，开发 Agent 时应重视交互体验与用户粘性。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/07/24/why-cognition-bought-poke-ai-personality-is-becoming-a-competitive-advantage/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="anthropic-发布-opus-5-性能接近-fable-5-但成本减半" tabindex="-1">Anthropic 发布 Opus 5，性能接近 Fable 5 但成本减半 <a class="header-anchor" href="#anthropic-发布-opus-5-性能接近-fable-5-但成本减半" aria-label="Permalink to &quot;Anthropic 发布 Opus 5，性能接近 Fable 5 但成本减半&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-07-25">2026-07-25</time></p><p><img src="https://techcrunch.com/wp-content/uploads/2026/07/Screenshot-2026-07-24-at-12.47.38-PM.jpg?w=1166" alt="配图"></p><p>Anthropic 于 7 月 24 日发布最新旗舰模型 Claude Opus 5。官方称其在编程、Agent 任务及复杂推理方面显著提升，多项基准测试追平甚至反超 Fable 5，但 API 价格维持 Opus 4.8 水平（输入 5 美元/百万 Token，输出 25 美元/百万 Token），仅为 Fable 5 的一半。该模型已向 Claude 平台及 API 用户开放，更适合企业办公与日常高频场景。对读者：若需高性价比的强推理模型，Opus 5 是当前最优选，可优先评估其在自身工作流中的表现。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/07/24/anthropic-launches-opus-5/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="opus-5-实测炸场-网友称-差点从椅子上摔下来" tabindex="-1">Opus 5 实测炸场：网友称“差点从椅子上摔下来” <a class="header-anchor" href="#opus-5-实测炸场-网友称-差点从椅子上摔下来" aria-label="Permalink to &quot;Opus 5 实测炸场：网友称“差点从椅子上摔下来”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-25">2026-07-25</time></p><p>Opus 5 上线后引发社区疯狂测试。博主仅用 5 倍 Max 订阅额度的 27% 便搭建出高质量的 Rocket League 克隆版；另一测试中，Opus 5 Max 直接打破原有基准。Minecraft 复刻、物理机关模拟等场景均表现惊艳，被评价为“像把提示词丢进图像生成器，出来一整张能走进去的地图”。Anthropic 甚至为适配 Opus 5 的推理能力，将 Claude Code 系统提示词删减八成。对读者：Opus 5 的代码生成与物理模拟能力已接近甚至超越 Fable 5，开发者可尝试将其接入 Cursor 等工具以提升效率。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/460253.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="meta-ai-聊天机器人升级为个人助手-集成日历与深度研究" tabindex="-1">Meta AI 聊天机器人升级为个人助手：集成日历与深度研究 <a class="header-anchor" href="#meta-ai-聊天机器人升级为个人助手-集成日历与深度研究" aria-label="Permalink to &quot;Meta AI 聊天机器人升级为个人助手：集成日历与深度研究&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-07-25">2026-07-25</time></p><p><img src="https://platform.theverge.com/wp-content/uploads/sites/2/2026/07/04_Trending.jpg?quality=90&amp;strip=all&amp;crop=0%2C4.9744178812656%2C100%2C60.121795706945&amp;w=1200" alt="配图"></p><p>Meta 宣布对其 AI 聊天机器人进行重大更新，使其超越简单的问答与图像生成，转向生产力助手。新功能包括接入用户日历生成每日简报、协助规划活动，以及执行可引导的深度研究。Meta 称这是“迈向个人超级智能的下一步”，由最新模型驱动，旨在与 Gemini、ChatGPT 和 Claude 竞争。对读者：Meta AI 的日历集成与深度研究功能值得关注，若你深度使用 Meta 生态，可尝试将其作为日常信息聚合入口。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/970570/meta-ai-chatbot-productivity-update" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="阿里巴巴开源代码审查工具-open-code-review-混合架构-llm-agent" tabindex="-1">阿里巴巴开源代码审查工具 open-code-review：混合架构 + LLM Agent <a class="header-anchor" href="#阿里巴巴开源代码审查工具-open-code-review-混合架构-llm-agent" aria-label="Permalink to &quot;阿里巴巴开源代码审查工具 open-code-review：混合架构 + LLM Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">alibaba/open-code-review</span><time datetime="2026-07-26">2026-07-26</time></p><p><img src="https://opengraph.githubassets.com/1/alibaba/open-code-review" alt="配图"></p><p>阿里巴巴开源并免费发布代码审查工具 open-code-review，采用确定性流水线 + LLM Agent 的混合架构，可在行级提供精确评论。内置针对 NPE、线程安全、XSS、SQL 注入等场景的微调规则集，兼容 OpenAI 与 Anthropic API。该工具已在阿里内部大规模验证。对读者：团队可零成本引入此工具，在 CI/CD 中集成自动化代码审查，尤其适合对安全与质量要求较高的项目。</p><p class="news-entry-source"><a href="https://github.com/alibaba/open-code-review" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="citrolabs-ego-lite-专为-ai-agent-打造的最快浏览器" tabindex="-1">citrolabs/ego-lite：专为 AI Agent 打造的最快浏览器 <a class="header-anchor" href="#citrolabs-ego-lite-专为-ai-agent-打造的最快浏览器" aria-label="Permalink to &quot;citrolabs/ego-lite：专为 AI Agent 打造的最快浏览器&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">citrolabs/ego-lite</span><time datetime="2026-07-26">2026-07-26</time></p><p><img src="https://opengraph.githubassets.com/1/citrolabs/ego-lite" alt="配图"></p><p>ego-lite 定位为“AI Agent 最快的浏览器”，支持将用户的登录态共享给 Codex 或 Claude Code 等 Agent 以执行浏览器自动化，且不干扰用户操作。项目宣称零成本、零配置，旨在解决 Agent 在浏览器环境中身份认证与状态共享的痛点。对读者：若你频繁使用 AI 编码代理进行网页自动化测试或数据采集，ego-lite 可显著降低环境配置成本。</p><p class="news-entry-source"><a href="https://github.com/citrolabs/ego-lite" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const u=a(s,[["render",o]]);export{m as __pageData,u as default};
